'use strict';

// Input: Data change capture from subscription
// Structure: { value: { before: {}, after: {} }, topic: "", headers: {} }

// Extract the after state from the data change event
const history = $.value.after;

// Validate this is an update with endAt being set
const before = $.value.before;

if (!before || !history) {
  throw new Error('Missing before/after data in subscription payload');
}

// Only process when endAt is being set (was null, now has value)
if (before.endAt !== null && before.endAt !== undefined) {
  console.log(`Skipping: WorkcenterHistory ${history.id} - endAt was already set`);
  return null;
}

if (!history.endAt) {
  console.log(`Skipping: WorkcenterHistory ${history.id} - endAt still null`);
  return null;
}

// Validate required fields exist
if (!history.occurAt || !history.workcenterId) {
  throw new Error(`Missing required fields in WorkcenterHistory ${history.id}`);
}

// Calculate duration in milliseconds and minutes
const historyStart = new Date(history.occurAt);
const historyEnd = new Date(history.endAt);
const durationMs = historyEnd - historyStart;

// Validate duration is positive
if (durationMs <= 0) {
  throw new Error(
    `Invalid duration for WorkcenterHistory ${history.id}: ` +
    `endAt (${history.endAt}) must be after occurAt (${history.occurAt})`
  );
}

const durationMinutes = durationMs / (1000 * 60);

console.log(
  `Processing WorkcenterHistory ${history.id}: ` +
  `${durationMinutes.toFixed(2)} minutes (${history.occurAt} to ${history.endAt})`
);

// Prepare output for next step
return {
  workcenterId: history.workcenterId,
  historyId: history.id,
  historyStart: history.occurAt,
  historyEnd: history.endAt,
  durationMs: durationMs,
  durationMinutes: durationMinutes,
  modeId: history.modeId,
  stateId: history.stateId,
  scheduleId: history.scheduleId
};

data.query:
query GetModeAndAffectedHours(
  $modeId: String!
  $workcenterId: String!
  $historyStart: DateTime!
  $historyEnd: DateTime!
) {
  mode(where: { id: { _eq: $modeId } }) {
    edges {
      node {
        id
        code
        name
        countAsProductionTime
        countAsDowntime
        countAsPlannedDowntime
        oeeImpact
      }
    }
  }
  
  oeeHourly(
    where: {
      _and: [
        { workcenterId: { _eq: $workcenterId } }
        { scheduleHourStartAt: { _lt: $historyEnd } }
        { scheduleHourEndAt: { _gt: $historyStart } }
      ]
    }
    orderBy: { field: scheduleHourStartAt, direction: asc  }
  ) {
    edges {
      node {
        id
        workcenterId
        periodStartAt
        periodEndAt
        scheduleHourStartAt
        scheduleHourEndAt
        runMinutes(format:  milliseconds)
        setupMinutes(format: milliseconds)
        downtimeMinutes(format: milliseconds)
        idealCycleTime(format: milliseconds)
        plannedDowntimeMinutes(format: milliseconds)
        plannedMinutes(format: milliseconds)
        scheduledTime(format: milliseconds)
        modeChanges
        stateChanges
        scheduleId
      }
    }
  }
}

