// Restore context data
const historyStart = new Date($state.context.historyStart);
const historyEnd = new Date($state.context.historyEnd);

// Validate mode exists
if (!mode) {
  console.error(`Mode ${$state.context.modeId} not found - skipping history ${$state.context.historyId}`);
  return { skip: true, reason: 'mode_not_found' };
}

// Validate hours found
if (hours.length === 0) {
  console.log(`No OeeHourly records found for workcenter ${$state.context.workcenterId} - no updates needed`);
  return { skip: true, reason: 'no_hourly_records_found' };
}

console.log(`Processing mode ${mode.code} (${mode.name}) affecting ${hours.length} hours`);

// ═══════════════════════════════════════════════════════════════════════
// CRITICAL HELPER: Extract pure milliseconds from any duration format
// Handles edge case where GraphQL returns strings even with (format: milliseconds)
// ═══════════════════════════════════════════════════════════════════════
function extractMilliseconds(duration) {
  // Null/undefined check
  if (!duration && duration !== 0) return 0;
  
  // Already a number - return as-is
  if (typeof duration === 'number') {
    return Math.floor(duration);
  }
  
  // Duration object with milliseconds property
  if (typeof duration === 'object' && duration !== null && duration.milliseconds !== undefined) {
    return Math.floor(duration.milliseconds);
  }
  
  // String - could be ISO duration or numeric string
  if (typeof duration === 'string') {
    // Check if it's an ISO duration string (starts with PT)
    if (duration.startsWith('PT')) {
