    const parsed = parseFloat(duration);
    if (!isNaN(parsed)) {
      return Math.floor(parsed);
    }
    
    console.warn('Unknown string duration format: "' + duration + '"');
    return 0;
  }
  
  // Unknown type
  console.warn('Unknown duration type: ' + typeof duration + ', value: ' + JSON.stringify(duration));
  return 0;
}

// ═══════════════════════════════════════════════════════════════════════
// BUILD UPDATE PAYLOADS
// ═══════════════════════════════════════════════════════════════════════
const payload = hours.map(hour => {
  const scheduleStart = new Date(hour.scheduleHourStartAt);
  const scheduleEnd = new Date(hour.scheduleHourEndAt);
  
  // Calculate the TOTAL duration of this OEE hour (the absolute maximum)
  const hourTotalDurationMs = scheduleEnd - scheduleStart;
  
  if (hourTotalDurationMs <= 0) {
    console.error(`Invalid hour duration for ${hour.id}: scheduleHourEndAt must be after scheduleHourStartAt`);
    return null;
  }
  
  // Calculate overlap between history and schedule hour
  const overlapStart = historyStart > scheduleStart ? historyStart : scheduleStart;
  const overlapEnd = historyEnd < scheduleEnd ? historyEnd : scheduleEnd;
  const overlapMs = overlapEnd - overlapStart;
  
  if (overlapMs <= 0) {
    return null; // No overlap
  }
  
  // ═══════════════════════════════════════════════════════════════════════
  // EXTRACT PURE MILLISECONDS - Handles strings, objects, and numbers
  // ═══════════════════════════════════════════════════════════════════════
  const currentRunMs = extractMilliseconds(hour.runMinutes);
  const currentSetupMs = extractMilliseconds(hour.setupMinutes);
  const currentDowntimeMs = extractMilliseconds(hour.downtimeMinutes);
  const currentPlannedDowntimeMs = extractMilliseconds(hour.plannedDowntimeMinutes);
  const plannedMinutesMs = extractMilliseconds(hour.plannedMinutes);
  const scheduledTimeMs = extractMilliseconds(hour.scheduledTime);
  const currentModeChanges = hour.modeChanges || 0;
  const currentStateChanges = hour.stateChanges || 0;
  
  // Calculate currently accounted time
  const currentTotalAccountedMs = currentRunMs + currentSetupMs + currentDowntimeMs + currentPlannedDowntimeMs;
  
  // ═══════════════════════════════════════════════════════════════════════
  // CRITICAL PRE-FLIGHT CHECK: Validate existing data integrity
  // ═══════════════════════════════════════════════════════════════════════
  if (currentTotalAccountedMs > hourTotalDurationMs) {
    const excessMs = currentTotalAccountedMs - hourTotalDurationMs;
    console.error(
      `DATA INTEGRITY ERROR: Hour ${hour.id} ALREADY EXCEEDS duration! ` +
      `Current total: ${(currentTotalAccountedMs/60000).toFixed(2)}min ` +
      `(Run: ${(currentRunMs/60000).toFixed(2)}, ` +
      `Setup: ${(currentSetupMs/60000).toFixed(2)}, ` +
      `Downtime: ${(currentDowntimeMs/60000).toFixed(2)}, ` +
      `PlannedDT: ${(currentPlannedDowntimeMs/60000).toFixed(2)}) ` +
      `exceeds hour duration ${(hourTotalDurationMs/60000).toFixed(2)}min by ${(excessMs/60000).toFixed(2)}min. ` +
      `REFUSING to add more time.`
    );
    return null;
  }
  
  // Calculate remaining capacity
  const remainingCapacityMs = hourTotalDurationMs - currentTotalAccountedMs;
  
  if (remainingCapacityMs === 0) {
    console.log(`Hour ${hour.id} is 100% accounted - no capacity for additional time`);
    return null;
  }
  
  console.log(
    `Hour ${hour.id} current state: ${(currentTotalAccountedMs/60000).toFixed(2)}/${(hourTotalDurationMs/60000).toFixed(2)}min ` +
    `(${(currentTotalAccountedMs/hourTotalDurationMs*100).toFixed(1)}%), ` +
    `remaining: ${(remainingCapacityMs/60000).toFixed(2)}min`
  );
  
  // ═══════════════════════════════════════════════════════════════════════
  // SPECIAL HANDLING FOR NO-SCHEDULE MODE
  // ═══════════════════════════════════════════════════════════════════════
  let effectiveMode = mode;
  if (mode.code === 'NO-SCHEDULE' || mode.id === 'no-schedule') {
    if (hour.scheduleId) {
      console.warn(
        `Hour ${hour.id} has scheduleId ${hour.scheduleId} but workcenter is in NO-SCHEDULE mode - ` +
        `treating as UNPLANNED DOWNTIME`
      );
      effectiveMode = {
        ...mode,
        countAsProductionTime: true,
        countAsDowntime: true,
        countAsPlannedDowntime: false,
        code: 'NO-SCHEDULE-MISCLASS'
      };
    } else {
      console.log(`Hour ${hour.id} has no scheduleId and mode is NO-SCHEDULE - excluding from accumulation`);
      return null;
    }
  }
  
  // ═══════════════════════════════════════════════════════════════════════
  // DETERMINE CLASSIFICATION BASED ON MODE
  // ═══════════════════════════════════════════════════════════════════════
  let runIncrement = 0;
  let setupIncrement = 0;
  let downtimeIncrement = 0;
  let plannedDowntimeIncrement = 0;
  
  if (effectiveMode.countAsPlannedDowntime) {
    // MAINT, ENG - Planned downtime (excluded from OEE)
    plannedDowntimeIncrement = overlapMs;
    console.log(`Mode ${effectiveMode.code}: Planned downtime - excluded from OEE`);
  } else if (!effectiveMode.countAsProductionTime) {
    // Outside production entirely (shouldn't reach here after NO-SCHEDULE handling)
    console.log(`Mode ${effectiveMode.code}: Outside production time - no accumulation`);
    return null;
  } else {
    // Within production time
    if (effectiveMode.countAsDowntime) {
      // DISABLED, OFF, or misclassified NO-SCHEDULE
      downtimeIncrement = overlapMs;
    } else if (effectiveMode.code === 'PROD') {
      runIncrement = overlapMs;
    } else if (['SETUP', 'CLEAN', 'CLEANING', 'IDLE'].includes(effectiveMode.code)) {
      setupIncrement = overlapMs;
    } else {
      setupIncrement = overlapMs; // Default to setup
    }
  }
  
  // Calculate total increment
  const totalIncrementMs = runIncrement + setupIncrement + downtimeIncrement + plannedDowntimeIncrement;
  
  // ═══════════════════════════════════════════════════════════════════════
  // CAPACITY CHECK: Will this increment fit?
  // ═══════════════════════════════════════════════════════════════════════
  if (totalIncrementMs > remainingCapacityMs) {
    const excessMs = totalIncrementMs - remainingCapacityMs;
    
    console.warn(
      `CAPACITY WARNING: Hour ${hour.id} - requested ${(totalIncrementMs/60000).toFixed(2)}min ` +
      `but only ${(remainingCapacityMs/60000).toFixed(2)}min remaining. ` +
      `Excess: ${(excessMs/60000).toFixed(2)}min. Capping proportionally.`
    );
    
    // Proportionally reduce all increments to fit exactly
    const scaleFactor = remainingCapacityMs / totalIncrementMs;
    
    runIncrement = Math.floor(runIncrement * scaleFactor);
    setupIncrement = Math.floor(setupIncrement * scaleFactor);
    downtimeIncrement = Math.floor(downtimeIncrement * scaleFactor);
    plannedDowntimeIncrement = Math.floor(plannedDowntimeIncrement * scaleFactor);
    
    // Assign any rounding remainder to the largest increment
    const adjustedTotal = runIncrement + setupIncrement + downtimeIncrement + plannedDowntimeIncrement;
    const remainder = remainingCapacityMs - adjustedTotal;
    
    if (remainder > 0) {
      if (runIncrement >= setupIncrement && runIncrement >= downtimeIncrement && runIncrement >= plannedDowntimeIncrement) {
        runIncrement += remainder;
      } else if (setupIncrement >= downtimeIncrement && setupIncrement >= plannedDowntimeIncrement) {
        setupIncrement += remainder;
      } else if (downtimeIncrement >= plannedDowntimeIncrement) {
        downtimeIncrement += remainder;
      } else {
        plannedDowntimeIncrement += remainder;
      }
    }
  }
  
  // ═══════════════════════════════════════════════════════════════════════
  // CALCULATE NEW TOTALS - ENSURE PURE NUMBERS
  // ═══════════════════════════════════════════════════════════════════════
  const newRunMs = Math.floor(currentRunMs + runIncrement);
  const newSetupMs = Math.floor(currentSetupMs + setupIncrement);
  const newDowntimeMs = Math.floor(currentDowntimeMs + downtimeIncrement);
  const newPlannedDowntimeMs = Math.floor(currentPlannedDowntimeMs + plannedDowntimeIncrement);
  
  // ═══════════════════════════════════════════════════════════════════════
  // FINAL VALIDATION: Absolute guarantee we don't exceed
  // ═══════════════════════════════════════════════════════════════════════
  const finalTotalMs = newRunMs + newSetupMs + newDowntimeMs + newPlannedDowntimeMs;
  
  if (finalTotalMs > hourTotalDurationMs) {
    const excessMs = finalTotalMs - hourTotalDurationMs;
    console.error(
      `CRITICAL LOGIC ERROR: Hour ${hour.id} final total ${(finalTotalMs/60000).toFixed(4)}min ` +
      `exceeds duration ${(hourTotalDurationMs/60000).toFixed(4)}min by ${(excessMs/1000).toFixed(4)}s! ` +
      `This indicates a bug in the capping logic. REFUSING UPDATE.`
    );
    return null;
  }
  
  // Verify our increment was within allowed capacity
  const actualIncrementMs = finalTotalMs - currentTotalAccountedMs;
  if (actualIncrementMs > remainingCapacityMs) {
    console.error(
      `CRITICAL LOGIC ERROR: Increment ${(actualIncrementMs/60000).toFixed(4)}min ` +
      `exceeds remaining capacity ${(remainingCapacityMs/60000).toFixed(4)}min. REFUSING UPDATE.`
    );
    return null;
  }
  
  // Calculate accounting percentage
  const percentAccounted = (finalTotalMs / hourTotalDurationMs * 100).toFixed(1);
  
  // ═══════════════════════════════════════════════════════════════════════
  // ISO 22400-2 AVAILABILITY CALCULATION
  // ═══════════════════════════════════════════════════════════════════════
  // Availability = (Planned Production Time - Downtime) / Planned Production Time
  // Where: Planned Production Time = Scheduled Time - Planned Downtime
  // ═══════════════════════════════════════════════════════════════════════
  let newAvailability = null;
  let calculatedPlannedMinutesMs = plannedMinutesMs;
  
  // If plannedMinutes is not pre-calculated, derive it
  if (!calculatedPlannedMinutesMs && scheduledTimeMs > 0) {
    calculatedPlannedMinutesMs = scheduledTimeMs - newPlannedDowntimeMs;
  }
  
  if (calculatedPlannedMinutesMs > 0) {
    const actualProductionTimeMs = calculatedPlannedMinutesMs - newDowntimeMs;
    newAvailability = actualProductionTimeMs / calculatedPlannedMinutesMs;
    
    // Clamp to 0-1 range
    if (newAvailability < 0) newAvailability = 0;
    if (newAvailability > 1) newAvailability = 1;
  }
  
  console.log(
    `✓ Hour ${hour.id}: +${(actualIncrementMs/60000).toFixed(2)}min ${effectiveMode.code} ` +
    `(R:${(runIncrement/60000).toFixed(2)} S:${(setupIncrement/60000).toFixed(2)} ` +
    `D:${(downtimeIncrement/60000).toFixed(2)} PD:${(plannedDowntimeIncrement/60000).toFixed(2)}) | ` +
    `Total: ${(finalTotalMs/60000).toFixed(2)}/${(hourTotalDurationMs/60000).toFixed(2)}min (${percentAccounted}%) | ` +
    `Avail: ${newAvailability !== null ? (newAvailability * 100).toFixed(1) + '%' : 'N/A'}`
  );
  
  // ═══════════════════════════════════════════════════════════════════════
  // BUILD UPDATE PAYLOAD - PURE NUMBERS ONLY (milliseconds)
  // ═══════════════════════════════════════════════════════════════════════
  const update = {
    runMinutes: newRunMs,                          // Pure number (milliseconds)
    setupMinutes: newSetupMs,                      // Pure number (milliseconds)
    downtimeMinutes: newDowntimeMs,                // Pure number (milliseconds)
    plannedDowntimeMinutes: newPlannedDowntimeMs,  // Pure number (milliseconds)
    modeChanges: currentModeChanges + 1,
    stateChanges: currentStateChanges + 1
  };
  
  if (newAvailability !== null) {
    update.availability = newAvailability;
  }
  
  // Final type verification
  if (typeof update.runMinutes !== 'number' || isNaN(update.runMinutes)) {
    console.error(`ERROR: runMinutes is ${typeof update.runMinutes}, not number!`);
    return null;
  }
  if (typeof update.setupMinutes !== 'number' || isNaN(update.setupMinutes)) {
    console.error(`ERROR: setupMinutes is ${typeof update.setupMinutes}, not number!`);
    return null;
  }
  if (typeof update.downtimeMinutes !== 'number' || isNaN(update.downtimeMinutes)) {
    console.error(`ERROR: downtimeMinutes is ${typeof update.downtimeMinutes}, not number!`);
    return null;
  }
  if (typeof update.plannedDowntimeMinutes !== 'number' || isNaN(update.plannedDowntimeMinutes)) {
    console.error(`ERROR: plannedDowntimeMinutes is ${typeof update.plannedDowntimeMinutes}, not number!`);
    return null;
  }
  
  return {
    hourId: hour.id,
    where: { id: hour.id },
    update: update
  };
}).filter(Boolean);

// ═══════════════════════════════════════════════════════════════════════
// CREATE MUTEX LOCK KEY AND FINALIZE PAYLOAD
// ═══════════════════════════════════════════════════════════════════════
// Create mutex lock key from sorted hour IDs (prevents concurrent updates)
const mutexLockKey = payload.map(p => p.hourId).join(':');

console.log(`✓ Prepared ${payload.length} hour updates with guaranteed duration compliance`);
console.log(`Mutex lock key: ${mutexLockKey}`);

// Remove hourId from payload (not needed in mutation)
const cleanPayload = payload.map(({ hourId, ...rest }) => rest);

// Final debug log - show sample output
if (cleanPayload.length > 0) {
  console.log('=== SAMPLE OUTPUT ===');
  console.log(JSON.stringify(cleanPayload[0], null, 2));
  console.log('=====================');
}

return {
  payload: cleanPayload,
  mutexLockKey: mutexLockKey,
  historyId: $state.context.historyId
};

data.mutation:
mutation UpdateOeeHourly($payload: [OeeHourlyUpdatePayloadInput!]!) {
  updateOeeHourly(payload: $payload) {
    id
    runMinutes
    setupMinutes
    downtimeMinutes
    modeChanges
    stateChanges
    availability
  }
}
